      `CLAIM_OPENED sheet=${sheet} by=uma person=Ben amount=100.00 date=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=100.00 due-total=20.00 overdue-total=0.00`,
