      `CLAIM_OPENED sheet=${sheet} by=uma person=Cam amount=10.00 date=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Cam claimed=10.00 due-total=n/a overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=610.00 due-total=70.00 overdue-total=0.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=500.00 date=2026-03-01 number=FY2026-1 due=50.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ben amount=100.00 date=2026-03-01 number=FY2026-2 due=20.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=score-mid value=0`,
