      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=50.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=20.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Cam due-total=n/a`
    ]);
